function sayiCevir($value): float {
    $value = str_replace(['&#8378;','TL',' ',"\xc2\xa0"], '', trim((string)$value));
    if(strpos($value, ',') !== false){ $value = str_replace('.', '', $value); $value = str_replace(',', '.', $value); }
    return (float)$value;
}

