if(isset($_GET['excel'])){
    if(ob_get_length()){
        ob_end_clean();
    }

    $fileName = 'hakedis-detay-' . (int)$hakedis_id . '.xls';
    header('Content-Type: application/vnd.ms-excel; charset=UTF-8');
    header('Content-Disposition: attachment; filename="' . $fileName . '"');
    $cell = function($value){
        return htmlspecialchars(html_entity_decode((string)$value, ENT_QUOTES, 'UTF-8'), ENT_QUOTES, 'UTF-8');
    };

    echo "\xEF\xBB\xBF";
    echo '<html><head><meta charset="UTF-8"></head><body><table border="1">';
    echo '<tr><th>No</th><th>Tarih</th><th>İrsaliye</th><th>Çıkış</th><th>Varış</th><th>Baz</th><th>M.Baz</th><th>G.Motorin</th><th>Fark</th><th>%</th><th>Durum</th><th>Zam/İnd.</th><th>Güncel</th><th>KDV</th><th>Tevk.</th><th>Net</th></tr>';

    $sira = 1;
    foreach($satirlar as $row){
        $durum = $satirDurumlari[(int)$row['id']] ?? ['metin' => 'Sabit'];
        echo '<tr>';
        echo '<td>' . $sira++ . '</td>';
        echo '<td>' . date('d.m.Y', strtotime($row['tasima_tarihi'])) . '</td>';
        echo '<td>' . $cell($row['irsaliye_no']) . '</td>';
        echo '<td>' . $cell(gorunenMetin($row['cikis_noktasi'])) . '</td>';
        echo '<td>' . $cell(gorunenMetin($row['varis_noktasi'])) . '</td>';
        echo '<td>' . number_format((float)$row['birim_fiyat'], 2, ',', '.') . '</td>';
        echo '<td>' . number_format((float)$row['motorin_baz_fiyati'], 3, ',', '.') . '</td>';
        echo '<td>' . number_format((float)$row['gunluk_motorin_fiyati'], 3, ',', '.') . '</td>';
        echo '<td>' . number_format((float)$row['motorin_fark_tutari'], 2, ',', '.') . '</td>';
        echo '<td>' . number_format((float)$row['motorin_fark_yuzde'], 2, ',', '.') . '</td>';
        echo '<td>' . $cell($durum['metin']) . '</td>';
        echo '<td>' . number_format((float)$row['zam_indirim_tutari'], 2, ',', '.') . '</td>';
        echo '<td>' . number_format((float)$row['guncel_birim_fiyat'], 2, ',', '.') . '</td>';
        echo '<td>' . number_format((float)$row['kdv_tutari'], 2, ',', '.') . '</td>';
        echo '<td>' . number_format((float)$row['tevkifat_tutari'], 2, ',', '.') . '</td>';
        echo '<td>' . number_format((float)$row['net_tutar'], 2, ',', '.') . '</td>';
        echo '</tr>';
    }

    echo '<tr><td colspan="5"><b>TOPLAM</b></td><td><b>' . number_format($toplamBaz, 2, ',', '.') . '</b></td><td colspan="5"></td><td><b>' . number_format($toplamZam, 2, ',', '.') . '</b></td><td><b>' . number_format($toplamGuncel, 2, ',', '.') . '</b></td><td><b>' . number_format($toplamKdv, 2, ',', '.') . '</b></td><td><b>' . number_format($toplamTevkifat, 2, ',', '.') . '</b></td><td><b>' . number_format($toplamNet, 2, ',', '.') . '</b></td></tr>';
